module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\n\nimport {\n  EuiSuperSelect,\n  EuiSpacer,\n  EuiText,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [\n      {\n        value: 'option_one',\n        inputDisplay: 'Option one',\n        dropdownDisplay: (\n          <Fragment>\n            <strong>Option one</strong>\n            <EuiSpacer size=\"xs\" />\n            <EuiText size=\"s\" color=\"subdued\">\n              <p className=\"euiTextColor--subdued\">Has a short description giving more detail to the option.</p>\n            </EuiText>\n          </Fragment>\n        ),\n      },\n      {\n        value: 'option_two',\n        inputDisplay: 'Option two',\n        dropdownDisplay: (\n          <Fragment>\n            <strong>Option two</strong>\n            <EuiSpacer size=\"xs\" />\n            <EuiText size=\"s\" color=\"subdued\">\n              <p className=\"euiTextColor--subdued\">Has a short description giving more detail to the option.</p>\n            </EuiText>\n          </Fragment>\n        ),\n      },\n      {\n        value: 'option_three',\n        inputDisplay: 'Option three',\n        dropdownDisplay: (\n          <Fragment>\n            <strong>Option three</strong>\n            <EuiSpacer size=\"xs\" />\n            <EuiText size=\"s\" color=\"subdued\">\n              <p className=\"euiTextColor--subdued\">Has a short description giving more detail to the option.</p>\n            </EuiText>\n          </Fragment>\n        ),\n      },\n    ];\n\n    this.state = {\n      value: this.options[1].value,\n    };\n  }\n\n  onChange = (value) => {\n    this.setState({ value });\n  };\n\n  render() {\n    return (\n      <EuiSuperSelect\n        options={this.options}\n        valueOfSelected={this.state.value}\n        onChange={this.onChange}\n        itemLayoutAlign=\"top\"\n        hasDividers\n      />\n    );\n  }\n}\n"