module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiFlyout,\n  EuiFlyoutBody,\n  EuiFlyoutHeader,\n  EuiButton,\n  EuiText,\n  EuiTitle,\n  EuiCodeBlock,\n} from '../../../../src/components';\n\nexport class Flyout extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isFlyoutVisible: false,\n      isSwitchChecked: true,\n    };\n\n    this.closeFlyout = this.closeFlyout.bind(this);\n    this.showFlyout = this.showFlyout.bind(this);\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  }\n\n  closeFlyout() {\n    this.setState({ isFlyoutVisible: false });\n  }\n\n  showFlyout() {\n    this.setState({ isFlyoutVisible: true });\n  }\n\n  render() {\n    let flyout;\n\n    const htmlCode = `<EuiFlyout ...>\n  <EuiFlyoutHeader hasBorder>\n    <EuiTitle size=\"m\">\n      <h2></h2>\n    </EuiTitle>\n  </EuiFlyoutHeader>\n  <EuiFlyoutBody>\n    ...\n  </EuiFlyoutBody>\n</EuiFlyout>\n`;\n\n    if (this.state.isFlyoutVisible) {\n      flyout = (\n        <EuiFlyout\n          onClose={this.closeFlyout}\n          aria-labelledby=\"flyoutTitle\"\n        >\n          <EuiFlyoutHeader hasBorder>\n            <EuiTitle size=\"m\">\n              <h2 id=\"flyoutTitle\">\n                A typical flyout\n              </h2>\n            </EuiTitle>\n          </EuiFlyoutHeader>\n          <EuiFlyoutBody>\n            <EuiText>\n              <p>\n                For consistency across the many flyouts, please utilize the following code for\n                implementing the flyout with a header.\n              </p>\n            </EuiText>\n            <EuiCodeBlock language=\"html\">\n              {htmlCode}\n            </EuiCodeBlock>\n          </EuiFlyoutBody>\n        </EuiFlyout>\n      );\n    }\n\n    return (\n      <div>\n        <EuiButton onClick={this.showFlyout}>\n          Show flyout\n        </EuiButton>\n\n        {flyout}\n      </div>\n    );\n  }\n}\n"