module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiButton,\n  EuiCheckboxGroup,\n  EuiFieldText,\n  EuiForm,\n  EuiFormRow,\n  EuiFilePicker,\n  EuiRange,\n  EuiSelect,\n  EuiSwitch,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n\n    this.state = {\n      isSwitchChecked: false,\n      checkboxes: [{\n        id: `${idPrefix}0`,\n        label: 'Option one',\n      }, {\n        id: `${idPrefix}1`,\n        label: 'Option two is checked by default',\n      }, {\n        id: `${idPrefix}2`,\n        label: 'Option three',\n      }],\n      checkboxIdToSelectedMap: {\n        [`${idPrefix}1`]: true,\n      },\n      radios: [{\n        id: `${idPrefix}4`,\n        label: 'Option one',\n      }, {\n        id: `${idPrefix}5`,\n        label: 'Option two is selected by default',\n      }, {\n        id: `${idPrefix}6`,\n        label: 'Option three',\n      }],\n      radioIdSelected: `${idPrefix}5`,\n    };\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  }\n\n  onCheckboxChange = optionId => {\n    const newCheckboxIdToSelectedMap = ({ ...this.state.checkboxIdToSelectedMap, ...{\n      [optionId]: !this.state.checkboxIdToSelectedMap[optionId],\n    } });\n\n    this.setState({\n      checkboxIdToSelectedMap: newCheckboxIdToSelectedMap,\n    });\n  }\n\n  onRadioChange = optionId => {\n    this.setState({\n      radioIdSelected: optionId,\n    });\n  }\n\n  render() {\n    return (\n      <EuiForm>\n        <EuiFormRow\n          label=\"Text field\"\n          helpText=\"I am some friendly help text.\"\n        >\n          <EuiFieldText name=\"first\" />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Select (with no initial selection)\"\n        >\n          <EuiSelect\n            hasNoInitialSelection\n            options={[\n              { value: 'option_one', text: 'Option one' },\n              { value: 'option_two', text: 'Option two' },\n              { value: 'option_three', text: 'Option three' },\n            ]}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"File picker\"\n        >\n          <EuiFilePicker />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Range\"\n        >\n          <EuiRange\n            min={0}\n            max={100}\n            name=\"range\"\n            id=\"range\"\n          />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Use a switch instead of a single checkbox\"\n        >\n          <EuiSwitch\n            name=\"switch\"\n            label=\"Should we do this?\"\n            checked={this.state.isSwitchChecked}\n            onChange={this.onSwitchChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Checkboxes\"\n        >\n          <EuiCheckboxGroup\n            options={this.state.checkboxes}\n            idToSelectedMap={this.state.checkboxIdToSelectedMap}\n            onChange={this.onCheckboxChange}\n          />\n        </EuiFormRow>\n\n        <EuiButton type=\"submit\" fill>\n          Save form\n        </EuiButton>\n      </EuiForm>\n    );\n  }\n}\n"