module.exports = "import React, {\n  Component,\n} from 'react';\n\nimport {\n  EuiButton,\n  EuiButtonEmpty,\n  EuiFlexItem,\n  EuiFlexGroup,\n  EuiMutationObserver,\n  EuiPanel,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport class MutationObserver extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      lastMutation: 'no changes detected',\n      buttonColor: 'primary',\n      items: ['Item 1', 'Item 2', 'Item 3'],\n    };\n  }\n\n  toggleButtonColor = () => {\n    this.setState(({ buttonColor }) => ({\n      buttonColor: buttonColor === 'primary' ? 'warning' : 'primary'\n    }));\n  }\n\n  addItem = () => {\n    this.setState(({ items }) => ({\n      items: [...items, `Item ${items.length + 1}`]\n    }));\n  }\n\n  onMutation = ([{ type }]) => {\n    this.setState({\n      lastMutation: type === 'attributes'\n        ? 'button class name changed'\n        : 'DOM tree changed'\n    });\n  }\n\n  render() {\n    return (\n      <div>\n        <p>{this.state.lastMutation}</p>\n\n        <EuiSpacer/>\n\n        <EuiMutationObserver\n          observerOptions={{ subtree: true, attributes: true, childList: true }}\n          onMutation={this.onMutation}\n        >\n\n          <EuiButton color={this.state.buttonColor} fill={true} onClick={this.toggleButtonColor}>\n            Toggle button color\n          </EuiButton>\n\n          <EuiSpacer/>\n\n          <EuiFlexGroup>\n            <EuiFlexItem grow={false}>\n              <EuiPanel grow={false}>\n                <ul>\n                  {this.state.items.map(item => <li key={item}>{item}</li>)}\n                </ul>\n                <EuiSpacer size=\"s\"/>\n                <EuiButtonEmpty onClick={this.addItem}>add item</EuiButtonEmpty>\n              </EuiPanel>\n            </EuiFlexItem>\n          </EuiFlexGroup>\n\n        </EuiMutationObserver>\n      </div>\n    );\n  }\n}\n"