module.exports = "import React, {\n  Component,\n  Fragment,\n} from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiLink,\n  EuiHealth,\n  EuiButton,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n      selectedItems: [],\n    };\n\n    this.renderStatus = this.renderStatus.bind(this);\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const {\n      index: pageIndex,\n      size: pageSize,\n    } = page;\n\n    const {\n      field: sortField,\n      direction: sortDirection,\n    } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  onSelectionChange = (selectedItems) => {\n    this.setState({ selectedItems });\n  };\n\n  onClickDelete = () => {\n    const { selectedItems } = this.state;\n    store.deleteUsers(...selectedItems.map(user => user.id));\n\n    this.setState({\n      selectedItems: []\n    });\n  };\n\n  renderDeleteButton() {\n    const { selectedItems } = this.state;\n\n    if (selectedItems.length === 0) {\n      return;\n    }\n\n    return (\n      <EuiButton\n        color=\"danger\"\n        iconType=\"trash\"\n        onClick={this.onClickDelete}\n      >\n        Delete {selectedItems.length} Users\n      </EuiButton>\n    );\n  }\n\n  renderStatus(online) {\n    const color = online ? 'success' : 'danger';\n    const label = online ? 'Online' : 'Offline';\n    return <EuiHealth color={color}>{label}</EuiHealth>;\n  }\n\n  render() {\n    const {\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    } = this.state;\n\n    const {\n      pageOfItems,\n      totalItemCount,\n    } = store.findUsers(pageIndex, pageSize, sortField, sortDirection);\n\n    const deleteButton = this.renderDeleteButton();\n\n    const columns = [{\n      field: 'firstName',\n      name: 'First Name',\n      sortable: true,\n      truncateText: true,\n      hideForMobile: true,\n    }, {\n      field: 'lastName',\n      name: 'Last Name',\n      truncateText: true,\n      hideForMobile: true,\n    }, {\n      field: 'firstName',\n      name: 'Full Name',\n      isMobileHeader: true,\n      render: (name, item) => (\n        <EuiFlexGroup responsive={false} alignItems=\"center\">\n          <EuiFlexItem>{item.firstName} {item.lastName}</EuiFlexItem>\n          <EuiFlexItem grow={false}>{this.renderStatus(item.online)}</EuiFlexItem>\n        </EuiFlexGroup>\n      ),\n    }, {\n      field: 'github',\n      name: 'Github',\n      render: (username) => (\n        <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n          {username}\n        </EuiLink>\n      )\n    }, {\n      field: 'dateOfBirth',\n      name: 'Date of Birth',\n      dataType: 'date',\n      render: (date) => formatDate(date, 'dobLong'),\n      sortable: true\n    }, {\n      field: 'nationality',\n      name: 'Nationality',\n      render: (countryCode) => {\n        const country = store.getCountry(countryCode);\n        return `${country.flag} ${country.name}`;\n      }\n    }, {\n      field: 'online',\n      name: 'Online',\n      dataType: 'boolean',\n      render: (online) => (\n        this.renderStatus(online)\n      ),\n      sortable: true,\n      hideForMobile: true,\n    }];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8]\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    const selection = {\n      selectable: (user) => user.online,\n      selectableMessage: (selectable) => !selectable ? 'User is currently offline' : undefined,\n      onSelectionChange: this.onSelectionChange\n    };\n\n    return (\n      <Fragment>\n        {deleteButton}\n        <EuiBasicTable\n          items={pageOfItems}\n          itemId=\"id\"\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          isSelectable={true}\n          selection={selection}\n          onChange={this.onTableChange}\n        />\n      </Fragment>\n    );\n  }\n}\n"