module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiComboBox,\n  EuiButton,\n  EuiPopover,\n  EuiFormRow,\n  EuiModal,\n  EuiModalBody,\n  EuiModalHeader,\n  EuiModalHeaderTitle,\n  EuiOverlayMask,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [{\n      label: 'Titan',\n      'data-test-subj': 'titanOption',\n    }, {\n      label: 'Enceladus',\n    }, {\n      label: 'Mimas',\n    }, {\n      label: 'Dione',\n    }, {\n      label: 'Iapetus',\n    }, {\n      label: 'Phoebe',\n    }, {\n      label: 'Rhea',\n    }, {\n      label: 'Pandora is one of Saturn\\'s moons, named for a Titaness of Greek mythology',\n    }, {\n      label: 'Tethys',\n    }, {\n      label: 'Hyperion',\n    }];\n\n    this.state = {\n      selectedOptions: [this.options[2], this.options[4]],\n      isModalVisible: false,\n      isPopoverOpen: false,\n    };\n  }\n\n  closeModal = () => {\n    this.setState({ isModalVisible: false });\n  }\n\n  showModal = () => {\n    this.setState({ isModalVisible: true });\n  }\n\n  togglePopover = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  onChange = (selectedOptions) => {\n    this.setState({\n      selectedOptions,\n    });\n  };\n\n  onCreateOption = (searchValue, flattenedOptions = []) => {\n    if (!searchValue) {\n      return;\n    }\n\n    const normalizedSearchValue = searchValue.trim().toLowerCase();\n\n    if (!normalizedSearchValue) {\n      return;\n    }\n\n    const newOption = {\n      label: searchValue,\n    };\n\n    // Create the option if it doesn't exist.\n    if (flattenedOptions.findIndex(option =>\n      option.label.trim().toLowerCase() === normalizedSearchValue\n    ) === -1) {\n      this.options.push(newOption);\n    }\n\n    // Select the option.\n    this.setState(prevState => ({\n      selectedOptions: prevState.selectedOptions.concat(newOption),\n    }));\n  };\n\n  render() {\n    const { selectedOptions, isModalVisible, isPopoverOpen } = this.state;\n\n    const comboBox = (\n      <EuiComboBox\n        placeholder=\"Select or create options\"\n        options={this.options}\n        selectedOptions={selectedOptions}\n        onChange={this.onChange}\n        onCreateOption={this.onCreateOption}\n      />\n    );\n\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.togglePopover}\n      >\n        Open popover\n      </EuiButton>\n    );\n\n    let modal;\n\n    if (isModalVisible) {\n      modal = (\n        <EuiOverlayMask>\n          <EuiModal\n            onClose={this.closeModal}\n            style={{ width: '800px' }}\n          >\n            <EuiModalHeader>\n              <EuiModalHeaderTitle >\n                Combo box in a modal\n              </EuiModalHeaderTitle>\n            </EuiModalHeader>\n\n            <EuiModalBody>\n              {comboBox}\n            </EuiModalBody>\n          </EuiModal>\n        </EuiOverlayMask>\n      );\n    }\n\n    return (\n      <Fragment>\n        <EuiFormRow\n          label=\"Combo box\"\n          helpText=\"This combo box is inside of a form row\"\n        >\n          {comboBox}\n        </EuiFormRow>\n\n        <EuiPopover\n          id=\"popover\"\n          ownFocus\n          button={button}\n          isOpen={isPopoverOpen}\n          closePopover={this.closePopover}\n        >\n          <div style={{ width: '300px' }}>{comboBox}</div>\n        </EuiPopover>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiButton onClick={this.showModal}>\n          Show modal\n        </EuiButton>\n\n        {modal}\n      </Fragment>\n    );\n  }\n}\n"